'use client'

import Link from 'next/link'
import { useState, useEffect } from 'react'
import { FaBars, FaTimes, FaTelegram } from 'react-icons/fa'
import ThemeToggle from './ThemeToggle'
import { isAuthenticated } from '../lib/auth'

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false)
  const [isOwner, setIsOwner] = useState(false)

  useEffect(() => {
    setIsOwner(isAuthenticated())
  }, [])

  const navLinks = [
    { name: '🏠 الرئيسية', href: '/' },
    { name: '📰 سياسة', href: '/category/politics' },
    { name: '📊 اقتصاد', href: '/category/economy' },
    { name: '💻 تكنولوجيا', href: '/category/tech' },
    { name: '⚙️ لوحة التحكم', href: '/admin' },
    { name: 'ℹ️ عن الموقع', href: '/about' },
  ]

  // إضافة رابط لوحة المالك فقط إذا كان مسجل الدخول
  if (isOwner) {
    navLinks.push({ name: '👑 لوحة المالك', href: '/owner' })
  }

  return (
    <nav className="bg-white/90 dark:bg-black/90 backdrop-blur-md sticky top-0 z-50 border-b border-gray-200 dark:border-red-900/30">
      <div className="container-custom">
        <div className="flex justify-between items-center h-16">
          <Link href="/" className="text-2xl font-bold bg-gradient-to-r from-red-600 to-red-400 bg-clip-text text-transparent">
            ديب <span className="text-red-600">سورس</span> نيوز
          </Link>

          <div className="hidden md:flex space-x-6 space-x-reverse items-center">
            {navLinks.map((link) => (
              <Link 
                key={link.name} 
                href={link.href} 
                className="hover:text-red-600 transition-all duration-300 hover:scale-110"
              >
                {link.name}
              </Link>
            ))}
            
            <a 
              href="https://t.me/deepsourc" 
              target="_blank" 
              rel="noopener noreferrer"
              className="flex items-center gap-2 bg-gradient-to-r from-blue-600 to-blue-500 hover:from-blue-700 hover:to-blue-600 text-white px-4 py-2 rounded-full transition-all duration-300 hover:scale-105"
            >
              <FaTelegram className="animate-pulse" />
              <span>تليجرام</span>
            </a>
            
            <ThemeToggle />
          </div>

          <button onClick={() => setIsOpen(!isOpen)} className="md:hidden">
            {isOpen ? <FaTimes size={24} /> : <FaBars size={24} />}
          </button>
        </div>

        {isOpen && (
          <div className="md:hidden py-4 border-t border-gray-200 dark:border-gray-800">
            {navLinks.map((link) => (
              <Link 
                key={link.name} 
                href={link.href} 
                className="block py-3 hover:text-red-600 transition-all" 
                onClick={() => setIsOpen(false)}
              >
                {link.name}
              </Link>
            ))}
            
            <a 
              href="https://t.me/deepsourc" 
              target="_blank" 
              rel="noopener noreferrer"
              className="flex items-center gap-2 bg-gradient-to-r from-blue-600 to-blue-500 text-white px-4 py-2 rounded-full my-3 w-full justify-center"
            >
              <FaTelegram />
              <span>انضم لتليجرام</span>
            </a>
            
            <div className="py-3"><ThemeToggle /></div>
          </div>
        )}
      </div>
    </nav>
  )
}